import { PasswordInput } from '@absoluteui/components/password-input';

const host = document.querySelector<HTMLElement>('#password');
if (host) PasswordInput.create(host, { label: 'Password', name: 'password', required: true });

import { PasswordInput } from '@absoluteui/components/password-input';
import { PasswordStrengthMeter } from '@absoluteui/components/password-strength-meter';

const inputHost = document.querySelector<HTMLElement>('#new-password');
const meterHost = document.querySelector<HTMLElement>('#strength');
if (inputHost && meterHost) {
  const password = PasswordInput.create(inputHost, { label: 'New password', name: 'newPassword', autocomplete: 'new-password', required: true, minLength: 12 });
  const meter = PasswordStrengthMeter.create(meterHost, { input: password });
  password.update({ describedBy: [meter.describedById] });
}
